dataSet.query:
ВЫБРАТЬ полис.Страхователь, МИНИМУМ(полис.ДатаНачала) КАК ДатаНачала ПОМЕСТИТЬ ДатыПервыхПолисов ИЗ Документ.уб_СтраховойПолис КАК полис ГДЕ НЕ полис.СостояниеПолиса В (ЗНАЧЕНИЕ(Перечисление.уб_СостоянияПолиса.АннулированПолностью), ЗНАЧЕНИЕ(Перечисление.уб_СостоянияПолиса.АннулированЗаменаБланка), ЗНАЧЕНИЕ(Перечисление.уб_СостоянияПолиса.АннулированВыписанНовый)) И полис.СтраховаяПремия > 0
СГРУППИРОВАТЬ ПО полис.Страхователь ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ ОП.СтраховойПолис.Заявка КАК Заявка, ОП.СтраховойПолис.Заявка.Менеджер КАК Менеджер, ОП.СтраховойПолис.Заявка.Страхователь КАК Страхователь, ОП.СтраховойПолис.Заявка, ОП.СтраховойПолис.Заявка.Источник КАК Источник, ОП.СтраховойПолис.Заявка.ДатаСоздания КАК ДатаСоздания, ОП.Ссылка КАК Оплата, СУММА(ОП.НачисленнаяСуммаВзноса) КАК НачисленнаяСуммаВзноса, СУММА(ВЫБОР КОГДА ОП.ОплаченоФакт > 0 И ОП.КВСумма >= ОП.АВилиСкидкаСумма ТОГДА ОП.КВСумма - ОП.АВилиСкидкаСумма ИНАЧЕ 0 КОНЕЦ * (100 - ОП.ПроцентСКВ) / 100) КАК СКВ, СУММА(ОП.КВСумма) КАК КВСумма, ВЫРАЗИТЬ(ВЫБОР КОГДА СУММА(ОП.НачисленнаяСуммаВзноса) = 0 ТОГДА 0 ИНАЧЕ СУММА(ОП.КВСумма) * 100 / СУММА(ОП.НачисленнаяСуммаВзноса) КОНЕЦ КАК ЧИСЛО(15, 2)) КАК КВПроцент, ВЫБОР КОГДА ОП.ВидСП В (ЗНАЧЕНИЕ(Перечисление.уб_ВидыСтраховыхПродуктов.ВЗР), ЗНАЧЕНИЕ(Перечисление.уб_ВидыСтраховыхПродуктов.НС)) ТОГДА 0 КОГДА ОП.ВидСП В (ЗНАЧЕНИЕ(Перечисление.уб_ВидыСтраховыхПродуктов.Имущество), ЗНАЧЕНИЕ(Перечисление.уб_ВидыСтраховыхПродуктов.Произвольный)) И ОП.НачисленнаяСуммаВзноса < 1500 ТОГДА 0 КОГДА ОП.НомерВзноса = 1 И РАЗНОСТЬДАТ(ДатыПервыхПолисов.ДатаНачала, ОП.СтраховойПолис.Заявка.ДатаСоздания, МЕСЯЦ) < 3 ТОГДА 1 ИНАЧЕ 0 КОНЕЦ КАК НовыйКлиент, ОП.Подразделение, ЕСТЬNULL(ОП.Подразделение.НеИспользоватьПремированиеРекомендаций, ЛОЖЬ) КАК НеИспользоватьПремированиеРекомендаций, ОП.СтраховойПолис ПОМЕСТИТЬ Оплаты ИЗ Документ.уб_ОплатаПолисов КАК ОП ЛЕВОЕ СОЕДИНЕНИЕ ДатыПервыхПолисов КАК ДатыПервыхПолисов ПО ОП.СтраховойПолис.Страхователь = ДатыПервыхПолисов.Страхователь ГДЕ ОП.ИсключитьИзРасчетаЗП = ЛОЖЬ И НЕ ОП.СтраховойПолис.Ссылка = ЗНАЧЕНИЕ(Документ.уб_СтраховойПолис.ПустаяСсылка) И ОП.СтраховойПолис.ПометкаУдаления = ЛОЖЬ И ОП.ПометкаУдаления = ЛОЖЬ И ОП.НеВключатьВОтчетыПоставщикам = ЛОЖЬ И ОП.СхемаРасчетаСМенеджером = ЗНАЧЕНИЕ(ПланВидовРасчета.уб_РасчетЗарплатыМенеджерамОП.ПланПоСКВ) И ОП.СтраховойПолис.Заявка.ДатаСоздания >= &ДатаНачала И ОП.СтраховойПолис.Заявка.Источник = "Рекомендация" И ОП.СК.Наименование <> "-- КупиПолис --" И ОП.НомерВзноса = 1 И ОП.НачисленнаяСуммаВзноса > 100
СГРУППИРОВАТЬ ПО ОП.СтраховойПолис.Заявка.Менеджер, ОП.СтраховойПолис.Заявка.Страхователь, ОП.СтраховойПолис.Заявка, ОП.СтраховойПолис.Заявка.Источник, ОП.СтраховойПолис.Заявка.ДатаСоздания, ВЫБОР КОГДА ОП.ВидСП В (ЗНАЧЕНИЕ(Перечисление.уб_ВидыСтраховыхПродуктов.ВЗР), ЗНАЧЕНИЕ(Перечисление.уб_ВидыСтраховыхПродуктов.НС)) ТОГДА 0 КОГДА ОП.ВидСП В (ЗНАЧЕНИЕ(Перечисление.уб_ВидыСтраховыхПродуктов.Имущество), ЗНАЧЕНИЕ(Перечисление.уб_ВидыСтраховыхПродуктов.Произвольный)) И ОП.НачисленнаяСуммаВзноса < 1500 ТОГДА 0 КОГДА ОП.НомерВзноса = 1 И РАЗНОСТЬДАТ(ДатыПервыхПолисов.ДатаНачала, ОП.СтраховойПолис.Заявка.ДатаСоздания, МЕСЯЦ) < 3 ТОГДА 1 ИНАЧЕ 0 КОНЕЦ, ОП.Подразделение, ЕСТЬNULL(ОП.Подразделение.НеИспользоватьПремированиеРекомендаций, ЛОЖЬ), ОП.Ссылка, ОП.СтраховойПолис, ОП.СтраховойПолис.Заявка ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ РАЗЛИЧНЫЕ ПЕРВЫЕ 2000000 оплаты.Заявка КАК Заявка, оплаты.Менеджер КАК Менеджер, оплаты.Заявка.ИндексРекомендации КАК ИндексРекомендации, оплаты.Заявка.ИндексЦепочкиРекомендаций, МАКСИМУМ(оплаты.НовыйКлиент) КАК НовыйКлиент, оплаты.НеИспользоватьПремированиеРекомендаций ПОМЕСТИТЬ оценкаОплат ИЗ Оплаты КАК оплаты
СГРУППИРОВАТЬ ПО оплаты.Заявка, оплаты.Менеджер, оплаты.Заявка.ИндексРекомендации, оплаты.Заявка.ИндексЦепочкиРекомендаций, оплаты.НеИспользоватьПремированиеРекомендаций
УПОРЯДОЧИТЬ ПО оплаты.Заявка.ДатаСоздания ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ Оплаты.Заявка, СРЕДНЕЕ(Оплаты.КВПроцент) КАК КВПроцент, СРЕДНЕЕ(Оплаты.НачисленнаяСуммаВзноса) КАК НачисленнаяСуммаВзноса, МАКСИМУМ(Оплаты.Оплата.Подразделение) КАК Подразделение ПОМЕСТИТЬ СреднееПоОплатам ИЗ Оплаты КАК Оплаты ГДЕ Оплаты.Заявка.ИндексРекомендации <> 0 И Оплаты.НеИспользоватьПремированиеРекомендаций = ЛОЖЬ
СГРУППИРОВАТЬ ПО Оплаты.Заявка ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ Различные Оплаты.Заявка, Оплаты.Менеджер, Оплаты.Страхователь, Оплаты.СтраховойПолисЗаявка, Оплаты.Источник, Оплаты.ДатаСоздания, ВЫБОР КОГДА Оплаты.ДатаСоздания >= ДАТАВРЕМЯ(2019, 5, 1) ТОГДА СреднееПоОплатам.НачисленнаяСуммаВзноса ИНАЧЕ Оплаты.НачисленнаяСуммаВзноса КОНЕЦ КАК НачисленнаяСуммаВзноса, ВЫБОР КОГДА Оплаты.ДатаСоздания >= ДАТАВРЕМЯ(2019, 5, 1) ТОГДА СреднееПоОплатам.КВПроцент ИНАЧЕ Оплаты.КВПроцент КОНЕЦ КАК КВПроцент, Оплаты.НовыйКлиент, Оплаты.Заявка.ИндексЦепочкиРекомендаций, Оплаты.Заявка.ИндексРекомендации, Оплаты.НеИспользоватьПремированиеРекомендаций, ВЫБОР КОГДА Оплаты.ДатаСоздания >= ДАТАВРЕМЯ(2019, 5, 1) ТОГДА "" ИНАЧЕ Оплаты.СтраховойПолис КОНЕЦ КАК СтраховойПолис, ВЫБОР КОГДА Оплаты.Заявка.ИндексРекомендации = 16 ТОГДА "Премируемая" ИНАЧЕ "База" КОНЕЦ КАК Вид, Оплаты.Оплата.СреднийКВРекомендаций КАК ОплатаСреднийКВРекомендаций, Оплаты.Оплата.СредняяПремияРекомендаций КАК ОплатаСредняяПремияРекомендаций, СреднееПоОплатам.КВПроцент КАК КВПроцентСредний, СреднееПоОплатам.НачисленнаяСуммаВзноса КАК НачисленнаяСуммаВзносаСредний, СреднееПоОплатам.Подразделение ИЗ Оплаты КАК Оплаты ВНУТРЕННЕЕ СОЕДИНЕНИЕ СреднееПоОплатам КАК СреднееПоОплатам ПО Оплаты.Заявка = СреднееПоОплатам.Заявка ГДЕ Оплаты.Заявка.ИндексРекомендации <> 0 И Оплаты.НеИспользоватьПремированиеРекомендаций = ЛОЖЬ И (&Менеджер = ЗНАЧЕНИЕ(Справочник.ФизическиеЛица.ПустойАгент) ИЛИ Оплаты.Менеджер = &Менеджер) И (&ЭтоПолныеПрава = ИСТИНА ИЛИ Оплаты.Менеджер В (&СписокСотрудников))
ОБЪЕДИНИТЬ ВСЕ
ВЫБРАТЬ Различные Оплаты.Заявка, Оплаты.Менеджер, Оплаты.Страхователь, Оплаты.СтраховойПолисЗаявка, Оплаты.Источник, Оплаты.ДатаСоздания, ВЫБОР КОГДА Оплаты.ДатаСоздания >= ДАТАВРЕМЯ(2019, 5, 1) ТОГДА СреднееПоОплатам.НачисленнаяСуммаВзноса ИНАЧЕ Оплаты.НачисленнаяСуммаВзноса КОНЕЦ, ВЫБОР КОГДА Оплаты.ДатаСоздания >= ДАТАВРЕМЯ(2019, 5, 1) ТОГДА СреднееПоОплатам.КВПроцент ИНАЧЕ Оплаты.КВПроцент КОНЕЦ, Оплаты.НовыйКлиент, Оплаты.Заявка.ИндексЦепочкиРекомендаций + 1, 1, Оплаты.НеИспользоватьПремированиеРекомендаций, ВЫБОР КОГДА Оплаты.ДатаСоздания >= ДАТАВРЕМЯ(2019, 5, 1) ТОГДА "" ИНАЧЕ Оплаты.СтраховойПолис КОНЕЦ, "База", ВЫБОР КОГДА Оплаты.ДатаСоздания >= ДАТАВРЕМЯ(2019, 5, 1) ТОГДА СреднееПоОплатам.НачисленнаяСуммаВзноса ИНАЧЕ Оплаты.НачисленнаяСуммаВзноса КОНЕЦ, ВЫБОР КОГДА Оплаты.ДатаСоздания >= ДАТАВРЕМЯ(2019, 5, 1) ТОГДА СреднееПоОплатам.КВПроцент ИНАЧЕ Оплаты.КВПроцент КОНЕЦ, СреднееПоОплатам.КВПроцент, СреднееПоОплатам.НачисленнаяСуммаВзноса, СреднееПоОплатам.Подразделение
ИЗ Оплаты КАК Оплаты ВНУТРЕННЕЕ СОЕДИНЕНИЕ СреднееПоОплатам КАК СреднееПоОплатам ПО Оплаты.Заявка = СреднееПоОплатам.Заявка ГДЕ Оплаты.Заявка.ИндексРекомендации = 16 И Оплаты.ДатаСоздания >= ДАТАВРЕМЯ(2019, 5, 1) И Оплаты.НеИспользоватьПремированиеРекомендаций = ЛОЖЬ И (&Менеджер = ЗНАЧЕНИЕ(Справочник.ФизическиеЛица.ПустойАгент) ИЛИ Оплаты.Менеджер = &Менеджер) И (&ЭтоПолныеПрава = ИСТИНА ИЛИ Оплаты.Менеджер В (&СписокСотрудников))
